const $ = (s, el=document)=>el.querySelector(s);
const nf = new Intl.NumberFormat('en-US',{maximumFractionDigits:0});
const fmt = n => n>=1e9?`$${(n/1e9).toFixed(2)}B`:`$${(n/1e6).toFixed(1)}M`;
const idr = n => `Rp${nf.format(n)}`;
const clients=[['Nusantara Capital','Institutional','Gold'],['PT Arunika Energi','Corporate','Gold'],['Garuda Digital','Corporate','Silver'],['Indo Pacific Trade','Institutional','Platinum'],['Bumi Sentosa','Corporate','Silver'],['Mitra Teknologi','Corporate','Gold'],['Satria Fund','Institutional','Platinum'],['Cakrawala Niaga','Corporate','Silver'],['Karya Andalan','Corporate','Gold'],['Atlas Ventures','Institutional','Gold'],['Samudera Logistik','Corporate','Silver'],['Prima Konsultan','Corporate','Gold'],['Daya Sentral','Institutional','Platinum'],['Koin Indonesia','Corporate','Silver']];
const desks=['Desk 01','Desk 02','Desk 03','Desk 04','Desk 05'];
const types=['Fiat → USDT','USDT → IDR','Block Trade BTC','USDC → USD','Fiat → BTC'];
const assets=['USDT-TRC20','USDT-ERC20','BTC','USDC','IDR'];
const statuses=['Settled','Settled','Settled','Reconciled','Processing','Pending','Exception'];
const txs=Array.from({length:210},(_,i)=>{const d=new Date(2026,5+(i%5),1+(i*7)%27,8+i%9,15);const amount=4_500_000+(i*173_000)%58_000_000;return {id:`LBP-${String(260001+i).padStart(6,'0')}`,date:d,client:clients[i%clients.length][0],type:types[i%types.length],asset:assets[i%assets.length],in:amount,out:amount*(.991+(i%5)*.001),rate:15490+(i%17)*23,desk:desks[i%5],status:statuses[i%statuses.length],kyc:i%13?'Clear':'Review',fee:amount*.0025,spread:.22+(i%5)*.04,bank:['Mandiri','BCA','BRI'][i%3],txid:`0x${(1000000000+i*92821).toString(16)}b7ca9`}});
let lang=localStorage.lang||'EN', role=localStorage.role||'Management / Super Admin', page='dashboard', period='Monthly', modal=null, query='';
const tr={EN:{dash:'Dashboard',ledger:'Transaction Ledger',fiat:'Fiat Ledger',crypto:'Crypto Ledger',desks:'OTC Desks',clients:'Corporate Clients',aum:'AUM / Treasury',recon:'Reconciliation',reports:'Reports',export:'Export Center',audit:'Audit Trail',settings:'Settings'},ID:{dash:'Dasbor',ledger:'Buku Transaksi',fiat:'Buku Fiat',crypto:'Buku Kripto',desks:'Meja OTC',clients:'Klien Korporasi',aum:'AUM / Treasury',recon:'Rekonsiliasi',reports:'Laporan',export:'Pusat Ekspor',audit:'Jejak Audit',settings:'Pengaturan'}};
const T=k=>tr[lang][k]||k;
function landing(){return `<div class="landing"><nav class="nav"><div class="brand"><div class="brand-mark">L</div><div>PT LINTAS BATAS PEMBAYARAN<small>INSTITUTIONAL OTC</small></div></div><div class="nav-links"><span>Solutions</span><span>Institutional</span><span>Security</span><span>Insights</span></div><div class="nav-actions"><button class="lang" onclick="toggleLang()">${lang==='EN'?'ID':'EN'}</button><button class="btn btn-ghost" onclick="openPortal()">Sign In</button><button class="btn btn-primary" onclick="showModal('access')">Request Access</button></div></nav><section class="hero"><div class="hero-inner"><div><div class="eyebrow">INDONESIAN INSTITUTIONAL OTC DESK</div><h1>Confidence at every stage of settlement.</h1><p>PT Lintas Batas Pembayaran provides controlled execution for institutional fiat and digital-asset flows, designed around disciplined risk controls and transparent operations.</p><div class="hero-cta"><button class="btn btn-light" onclick="showModal('access')">Request Corporate Access</button><button class="btn btn-ghost" style="color:#fff;background:transparent;border-color:#ffffff55" onclick="openPortal()">Explore Portal →</button></div><div class="trust"><div><b>5</b>OTC desks</div><div><b>24/7</b>monitoring</div><div><b>Multi-rail</b>settlement</div></div></div><div class="hero-panel"><div class="panel-top"><span>Indicative Markets</span><span class="live-dot">● LIVE DEMO</span></div><div class="quote-grid"><div class="quote"><label>USDT / IDR</label><strong>15,842</strong><span class="up">+0.18% · buy</span></div><div class="quote"><label>BTC / USD</label><strong>68,420</strong><span class="up">+0.41% · buy</span></div><div class="quote"><label>USDC / USD</label><strong>1.0001</strong><span class="up">+0.01% · buy</span></div><div class="quote"><label>USD / IDR</label><strong>15,811</strong><span class="up">+0.06% · wire</span></div></div></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow" style="color:#059669">THE LBP APPROACH</div><h2>Institutional control,<br>built into the workflow.</h2></div><p>From client onboarding through reconciliation, each stage is designed for visibility, verification, and operational discipline.</p></div><div class="service-grid"><div class="service"><div class="service-icon">⇄</div><h3>Fiat on / off ramp</h3><p>Structured multi-rail settlement across domestic and international payment pathways.</p></div><div class="service"><div class="service-icon">◈</div><h3>Block trades</h3><p>Discreet, desk-managed execution with price and liquidity oversight.</p></div><div class="service"><div class="service-icon">⊞</div><h3>Conditional settlement</h3><p>Controlled process flows with defined approvals and reconciliation points.</p></div><div class="service"><div class="service-icon">≈</div><h3>Deep liquidity</h3><p>Tranche-based execution designed around available institutional capacity.</p></div></div></section><section class="asset-strip"><div class="section" style="padding:35px 28px"><div class="eyebrow" style="color:#059669;margin-bottom:15px">SUPPORTED ASSETS</div><div class="asset-list"><span class="asset">IDR</span><span class="asset">USD</span><span class="asset">USDT</span><span class="asset">USDC</span><span class="asset">BTC</span></div></div></section><section class="section"><div class="cta"><div><h2>Built for corporate<br>and institutional flows.</h2><p>Start a conversation with the LBP team to discuss your operating requirements.</p></div><button class="btn btn-light" onclick="showModal('access')">Request Access</button></div></section><footer class="footer"><div class="footer-inner"><div class="brand"><div class="brand-mark">L</div><div style="color:white">PT LINTAS BATAS PEMBAYARAN<small>INSTITUTIONAL OTC</small></div></div><span>© 2026 PT Lintas Batas Pembayaran · Demo interface</span></div></footer></div>`}
function allowed(k){const map={'Management / Super Admin':['dashboard','ledger','fiat','crypto','desks','clients','aum','recon','reports','export','audit','settings'],'OTC Desk Trader':['dashboard','ledger','desks'],'Finance / Treasury':['dashboard','fiat','crypto','aum','recon','reports','export'],'Compliance / AML':['dashboard','clients','ledger','recon','audit'],'Corporate Client':['dashboard','ledger','aum','reports']};return map[role].includes(k)}
const nav=[['dash','▦','dashboard'],['ledger','≡','ledger'],['fiat','▤','fiat'],['crypto','◇','crypto'],['desks','⌘','desks'],['clients','♙','clients'],['aum','◒','aum'],['recon','✓','recon'],['reports','▧','reports'],['export','⇩','export'],['audit','◷','audit'],['settings','⚙','settings']];
function portal(){let items=nav.filter(x=>allowed(x[2])).map(([n,i,k])=>`<button class="side-item ${page===k?'active':''}" onclick="go('${k}')"><b>${i}</b><span>${T(n)}</span></button>`).join('');return `<div class="portal"><aside class="sidebar"><div class="side-brand"><div class="brand-mark">L</div><span><b>LBP</b><br><small>OTC PLATFORM</small></span></div><div class="nav-group">OPERATIONS</div>${items}<div class="side-bottom"><button class="side-item" onclick="goHome()"><b>↗</b><span>Public site</span></button></div></aside><main class="main"><header class="portal-head"><div class="crumb">Portal / <b>${pageTitle()}</b></div><div class="head-controls"><button class="chip" onclick="toggleLang()">${lang==='EN'?'ID':'EN'}</button><select class="chip" onchange="setRole(this.value)">${['Management / Super Admin','OTC Desk Trader','Finance / Treasury','Compliance / AML','Corporate Client'].map(x=>`<option ${role===x?'selected':''}>${x}</option>`).join('')}</select><div class="profile">IH</div></div></header><section class="content">${view()}</section></main></div>${modal?modalHtml():''}`}
function pageTitle(){return ({dashboard:'OTC Management Dashboard',ledger:'Transaction Ledger',fiat:'Fiat Ledger',crypto:'Crypto Ledger',desks:'OTC Desk Configuration',clients:'B2B / Corporate Clients',aum:'AUM / Treasury',recon:'Reconciliation',reports:'Reports',export:'Export Center',audit:'Audit Trail',settings:'Settings'})[page]}
function kpi(label,value,sub='+ 12.4% vs prior period'){return `<div class="kpi"><label>${label}</label><strong>${value}</strong><span>↗ ${sub}</span></div>`}
function dashboard(){const vol=txs.reduce((a,b)=>a+b.in,0), settled=txs.filter(x=>x.status==='Settled').length;return `<div class="page-title"><div><h1>OTC Management Dashboard</h1><p>Consolidated ledger overview · Demo data</p></div><div class="periods">${['Today','Daily','Weekly','Monthly','Since Inception'].map(x=>`<button class="period ${period===x?'active':''}" onclick="setPeriod('${x}')">${x}</button>`).join('')}</div></div><div class="role-note">Viewing as <b>${role}</b> · All figures are generated from the master transaction ledger.</div><div class="kpis">${kpi('Gross OTC volume',fmt(vol))}${kpi('Fiat IN',fmt(vol*.53))}${kpi('Crypto OUT',fmt(vol*.44))}${kpi('Net revenue',fmt(vol*.0028))}${kpi('AUM',fmt(vol*.078),'2.7% monthly')}${kpi('Transactions',nf(txs.length),'19 this period')}${kpi('Reconciled',`${Math.round(settled/txs.length*100)}%`,'target ≥ 98%')}${kpi('Open exceptions','03','requires review')}</div><div class="grid-2"><div class="card"><div class="card-title">Settlement flow <span class="chip">${period}</span></div><div class="flow"><div class="flow-box"><label>BANK IN</label><strong>${fmt(vol*.53)}</strong></div><div class="arrow">→</div><div class="flow-box core"><label>TREASURY CORE</label><strong>${fmt(vol*.91)}</strong></div><div class="arrow">→</div><div class="flow-box"><label>CRYPTO OUT</label><strong>${fmt(vol*.44)}</strong></div></div><div class="legend"><span><i class="dot" style="background:#059669"></i>Reconciled</span><span><i class="dot" style="background:#1e40af"></i>Processing</span><span><i class="dot" style="background:#d97706"></i>Pending review</span></div></div><div class="card"><div class="card-title">Desk allocation <span class="chip">5 desks</span></div>${desks.map((d,i)=>`<div class="barrow"><label>${d}</label><div class="bar"><i style="width:${78-i*9}%"></i></div><span>${fmt(vol*(.25-i*.025))}</span></div>`).join('')}</div></div><div class="card" style="margin-top:15px"><div class="card-title">Recent ledger activity <button class="btn btn-ghost" onclick="go('ledger')">View ledger</button></div>${table(txs.slice(0,7))}</div>`}
function table(data,mode='ledger'){return `<div style="overflow:auto"><table class="data-table"><thead><tr><th>TX ID</th><th>Date / Time</th><th>Client</th><th>Type</th><th>Asset</th><th>IN</th><th>OUT</th><th>Desk</th><th>Status</th><th>KYC/AML</th></tr></thead><tbody>${data.map(x=>`<tr onclick="showTx('${x.id}')"><td class="mono" style="color:#1e40af;font-weight:700">${x.id}</td><td>${x.date.toLocaleDateString('en-GB')}<br><small>${x.date.toTimeString().slice(0,5)}</small></td><td>${x.client}</td><td>${x.type}</td><td class="mono">${x.asset}</td><td class="mono">${fmt(x.in)}</td><td class="mono">${fmt(x.out)}</td><td>${x.desk}</td><td><span class="pill ${x.status.toLowerCase()}">${x.status}</span></td><td><span class="pill ${x.kyc==='Clear'?'reconciled':'pending'}">${x.kyc}</span></td></tr>`).join('')}</tbody></table></div>`}
function ledger(){let data=txs.filter(x=>Object.values(x).join(' ').toLowerCase().includes(query.toLowerCase()));return `<div class="page-title"><div><h1>Master Transaction Ledger</h1><p>${data.length} transactions · single source of truth</p></div><button class="btn btn-primary" onclick="showModal('newtx')">+ New transaction</button></div><div class="card"><div class="table-tools"><input class="search" placeholder="Search ID, client, asset…" value="${query}" oninput="search(this.value)"><select class="chip" onchange="filterStatus(this.value)"><option value="">All statuses</option><option>Settled</option><option>Processing</option><option>Pending</option><option>Exception</option></select><button class="btn btn-ghost" onclick="downloadCSV()">⇩ Export CSV</button></div>${table(data)}</div>`}
function genericLedger(kind){let data=kind==='fiat'?txs.filter(x=>x.asset==='IDR'||x.type.includes('Fiat')):txs.filter(x=>x.asset.includes('USDT')||x.asset==='BTC'||x.asset==='USDC');return `<div class="page-title"><div><h1>${kind==='fiat'?'Fiat Ledger':'Crypto Ledger'}</h1><p>${kind==='fiat'?'Bank settlement rails · Mandiri · BCA · BRI':'On-chain deposits & withdrawals · confirmations monitored'}</p></div><button class="btn btn-ghost" onclick="downloadCSV()">⇩ Export</button></div><div class="card">${table(data.slice(0,60))}</div>`}
function desksView(){return `<div class="page-title"><div><h1>OTC Desks 01–05</h1><p>Client pricing, spread and fee configuration</p></div><button class="btn btn-primary" onclick="showModal('audit')">View edit audit</button></div><div class="card"><table class="data-table"><thead><tr><th>Desk</th><th>Buy Price</th><th>Sell Price</th><th>Spread %</th><th>Fee %</th><th>Live Client Price</th><th>Gross Spread</th><th>Desk Revenue</th><th></th></tr></thead><tbody>${desks.map((d,i)=>`<tr><td><b>${d}</b></td><td class="mono">${(15800-i*11).toLocaleString()}</td><td class="mono">${(15840-i*10).toLocaleString()}</td><td>${(.25+i*.03).toFixed(2)}%</td><td>0.20%</td><td class="mono">${(15838-i*10).toLocaleString()}</td><td class="mono">${fmt(4.8e6+i*1.6e6)}</td><td class="mono">${fmt(69000+i*8000)}</td><td><button class="btn btn-ghost" onclick="showModal('editdesk')">Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function clientsView(){return `<div class="page-title"><div><h1>B2B / Corporate Clients</h1><p>Client directory, onboarding and dossier status</p></div><button class="btn btn-primary" onclick="showModal('client')">+ Add client</button></div><div class="card"><table class="data-table"><thead><tr><th>Client</th><th>Segment</th><th>Tier</th><th>Transactions</th><th>Volume</th><th>Net Flow</th><th>AUM</th><th>KYC</th></tr></thead><tbody>${clients.map((x,i)=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${12+i*7}</td><td class="mono">${fmt((7+i*2.4)*1e6)}</td><td class="mono">${i%2?'+':'-'}${fmt((.8+i*.2)*1e6)}</td><td class="mono">${fmt((.5+i*.19)*1e6)}</td><td><span class="pill reconciled">Verified</span></td></tr>`).join('')}</tbody></table></div>`}
function aumView(){return `<div class="page-title"><div><h1>AUM / Treasury</h1><p>Reserve position and asset composition</p></div><button class="btn btn-ghost">Configure IDR equivalents</button></div><div class="kpis">${kpi('Opening AUM','$412.4M','since inception')}${kpi('Current AUM','$438.6M','6.4% growth')}${kpi('Net inflow','$31.8M','this month')}${kpi('Reserve coverage','112.8%','within policy')}</div><div class="grid-2"><div class="card"><div class="card-title">Asset reserve breakdown</div>${[['IDR reserve',38,'Rp2.18T'],['USDT',31,'$132.7M'],['USD',17,'$73.1M'],['BTC',9,'$39.6M'],['USDC',5,'$21.9M']].map(x=>`<div class="barrow"><label>${x[0]}</label><div class="bar"><i style="width:${x[1]}%;background:#059669"></i></div><span>${x[2]}</span></div>`).join('')}</div><div class="card"><div class="card-title">Treasury controls</div><p>Segregated settlement structures, monitored wallet limits, and multi-step execution approval applied across active flows.</p><div class="role-note">All figures derive from the master ledger in this demo.</div></div></div>`}
function reconView(){let rows=txs.slice(0,18);return `<div class="page-title"><div><h1>Reconciliation</h1><p>Expected versus actual bank and on-chain settlement</p></div><button class="btn btn-primary" onclick="showModal('exception')">+ Log exception</button></div><div class="kpis">${kpi('Bank reconciled','98.7%','expected vs actual')}${kpi('Wallet reconciled','99.1%','on-chain confirmed')}${kpi('Exceptions','03','open investigation')}${kpi('Pending approvals','02','reversal workflow')}</div><div class="card" style="margin-top:15px"><div class="card-title">Reconciliation queue</div><table class="data-table"><thead><tr><th>Reference</th><th>Expected</th><th>Actual</th><th>Rail / Chain</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((x,i)=>`<tr><td class="mono">${x.id}</td><td>${fmt(x.in)}</td><td>${fmt(i%7?x.in:x.in*.993)}</td><td>${i%2?'TRC20':'RTGS'}</td><td><span class="pill ${i%7?'reconciled':'exception'}">${i%7?'Reconciled':'Exception'}</span></td><td>${i%7?'—':'Investigate'}</td></tr>`).join('')}</tbody></table></div>`}
function reportsView(){return `<div class="page-title"><div><h1>Reports</h1><p>Generate operational and management views from the ledger</p></div></div><div class="service-grid">${['Daily operations','Weekly desk review','Monthly management','Since inception'].map((x,i)=>`<div class="service"><div class="service-icon">▧</div><h3>${x}</h3><p>Ledger-derived volumes, settlements, revenue, reconciliation and exceptions.</p><button class="btn btn-primary" onclick="showModal('report${i}')">Generate</button></div>`).join('')}</div>`}
function exportView(){return `<div class="page-title"><div><h1>Export Center</h1><p>Filter, package and export ledger-based records</p></div></div><div class="card"><div class="form-grid"><label>Report type<select><option>Transaction ledger</option><option>Reconciliation</option><option>Client statement</option></select></label><label>Date range<select><option>Since inception</option><option>This month</option><option>Custom range</option></select></label><label>Client<select><option>All clients</option>${clients.map(x=>`<option>${x[0]}</option>`)}</select></label><label>Desk<select><option>All desks</option>${desks.map(x=>`<option>${x}</option>`)}</select></label></div><div style="display:flex;gap:9px;margin-top:20px"><button class="btn btn-primary" onclick="downloadCSV()">Export CSV</button><button class="btn btn-ghost" onclick="alert('Demo: Multi-sheet XLSX workbook prepared with 18 sheets.')">Export XLSX (18 sheets)</button><button class="btn btn-ghost" onclick="window.print()">Printable PDF view</button></div></div>`}
function auditView(){return `<div class="page-title"><div><h1>Audit Trail</h1><p>Immutable ledger of operating events · void / reversal only</p></div></div><div class="card"><table class="data-table"><thead><tr><th>Timestamp</th><th>User</th><th>Action</th><th>Object</th><th>Old value</th><th>New value</th></tr></thead><tbody>${Array.from({length:18},(_,i)=>`<tr><td class="mono">2026-10-${String(20-i%5).padStart(2,'0')} 1${i%8}:2${i}</td><td>${['Treasury Ops','Desk 03 Trader','Compliance Team'][i%3]}</td><td>${['Updated status','Approved tranche','Reconciled bank ref'][i%3]}</td><td class="mono">${txs[i].id}</td><td>${i%2?'Processing':'—'}</td><td>${['Settled','Approved','Reconciled'][i%3]}</td></tr>`).join('')}</tbody></table></div>`}
function settingsView(){return `<div class="page-title"><div><h1>Settings</h1><p>Demo defaults and reference rate controls</p></div><button class="btn btn-primary" onclick="alert('Settings saved in this browser demo.')">Save changes</button></div><div class="grid-2"><div class="card"><div class="card-title">Exchange rates</div><div class="form-grid"><label>USD / IDR<input value="15,811"></label><label>USDT / IDR<input value="15,842"></label><label>USDC / USD<input value="1.0001"></label><label>Default language<select><option>English</option><option>Bahasa Indonesia</option></select></label></div></div><div class="card"><div class="card-title">Desk defaults</div><p>Default fee: 0.20%<br>Default spread target: 0.25%<br>Transaction approval: dual control</p></div></div>`}
function view(){return ({dashboard,ledger,fiat:()=>genericLedger('fiat'),crypto:()=>genericLedger('crypto'),desks:desksView,clients:clientsView,aum:aumView,recon:reconView,reports:reportsView,export:exportView,audit:auditView,settings:settingsView})[page]()}
function modalHtml(){let body=modal==='access'?`<h2>Request corporate access</h2><p>Submit your institution details and the LBP team will contact you.</p><div class="form-grid"><label>Company<input placeholder="Company legal name"></label><label>Work email<input placeholder="name@company.com"></label><label>Contact name<input placeholder="Full name"></label><label>Estimated monthly volume<select><option>Choose range</option><option>USD 1M–10M</option><option>USD 10M–50M</option><option>USD 50M+</option></select></label></div><button class="btn btn-primary" style="margin-top:18px" onclick="submitted()">Submit request</button>`:modal==='newtx'?`<h2>New transaction</h2><p>Demo workflow: a created transaction is logged locally for this session.</p><div class="form-grid"><label>Client<select>${clients.map(x=>`<option>${x[0]}</option>`)}</select></label><label>Transaction type<select>${types.map(x=>`<option>${x}</option>`)}</select></label><label>Amount<input value="5000000"></label><label>Settlement desk<select>${desks.map(x=>`<option>${x}</option>`)}</select></label></div><button class="btn btn-primary" style="margin-top:18px" onclick="submitted('Transaction created as Pending compliance review.')">Create transaction</button>`:modal==='audit'?`<h2>Desk configuration audit</h2><p>2026-10-21 10:42 · Treasury Ops changed Desk 02 sell spread from 0.26% to 0.28%.</p><p>2026-10-21 09:12 · Desk 04 Trader updated client price band.</p>`:modal==='editdesk'?`<h2>Edit desk pricing</h2><div class="form-grid"><label>Buy price<input value="15,800"></label><label>Sell price<input value="15,840"></label><label>Spread %<input value="0.25"></label><label>Fee %<input value="0.20"></label></div><button class="btn btn-primary" style="margin-top:18px" onclick="submitted('Desk price updated and audit event recorded.')">Save desk configuration</button>`:modal==='client'?`<h2>Add corporate client</h2><div class="form-grid"><label>Legal name<input></label><label>Segment<select><option>Corporate</option><option>Institutional</option></select></label><label>Entity country<input value="Indonesia"></label><label>Tier<select><option>Silver</option><option>Gold</option><option>Platinum</option></select></label></div><button class="btn btn-primary" style="margin-top:18px" onclick="submitted('Client dossier created as Draft.')">Create dossier</button>`:modal==='exception'?`<h2>Log reconciliation exception</h2><div class="form-grid"><label>Reference ID<input placeholder="LBP-260001"></label><label>Exception type<select><option>Bank mismatch</option><option>Wallet mismatch</option><option>Confirmation delay</option></select></label></div><button class="btn btn-primary" style="margin-top:18px" onclick="submitted('Exception logged and assigned for investigation.')">Log exception</button>`:`<h2>Report generator</h2><p>Your report will be generated from the master ledger with the currently selected filters.</p><button class="btn btn-primary" onclick="submitted('Report generated. In this demo, download packaging is simulated.')">Generate report</button>`;return `<div class="modal-wrap"><div class="modal"><div class="modal-head"><span class="eyebrow" style="color:#059669">LBP OPERATIONS</span><button class="close" onclick="closeModal()">×</button></div>${body}</div></div>`}
function render(){document.getElementById('app').innerHTML=location.hash==='#portal'?portal():landing()}
function openPortal(){location.hash='portal';render()}function goHome(){location.hash='';render()}function go(p){page=p;render()}function toggleLang(){lang=lang==='EN'?'ID':'EN';localStorage.lang=lang;render()}function setRole(r){role=r;localStorage.role=r;if(!allowed(page))page='dashboard';render()}function setPeriod(p){period=p;render()}function search(v){query=v;render()}function filterStatus(v){query=v;render()}function closeModal(){modal=null;render()}function showModal(m){modal=m;render()}function submitted(msg='Request submitted. The LBP team will review your details.'){alert(msg);closeModal()}function showTx(id){const x=txs.find(x=>x.id===id);modal='tx';document.getElementById('app').insertAdjacentHTML('beforeend',`<div class="modal-wrap"><div class="modal"><div class="modal-head"><h2>Transaction ${x.id}</h2><button class="close" onclick="document.querySelector('.modal-wrap').remove()">×</button></div><p><span class="pill ${x.status.toLowerCase()}">${x.status}</span> &nbsp; <span class="pill reconciled">${x.kyc}</span></p><div class="form-grid"><label>Counterparty<input value="${x.client}" readonly></label><label>Liquidity Provider<input value="Pacific Digital LP" readonly></label><label>Spread %<input value="${x.spread.toFixed(2)}%" readonly></label><label>Fee %<input value="0.25%" readonly></label><label>Bank reference<input value="${x.bank}-REF-${x.id.slice(-4)}" readonly></label><label>Operator<input value="OTC Operations" readonly></label><label>Blockchain TXID<input value="${x.txid}" readonly></label><label>Settlement desk<input value="${x.desk}" readonly></label></div><div style="margin-top:18px;display:flex;gap:9px"><button class="btn btn-primary" onclick="alert('Demo voucher generated.')">Download voucher</button><button class="btn btn-ghost" onclick="alert('Explorer link opened in production.')">View explorer</button></div></div></div>`)}function downloadCSV(){const csv=['TX ID,Date,Client,Type,Asset,IN,OUT,Desk,Status',...txs.map(x=>[x.id,x.date.toISOString(),x.client,x.type,x.asset,x.in,x.out,x.desk,x.status].join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='lbp-transaction-ledger.csv';a.click()}window.onhashchange=render;render();
